I haven't seen any games with the same interface behavior as the system, so I have no doubt that these settings will be used by default in every game. As for whether this problem can be solved via script - yes, but it is insanely difficult. All you can do directly with Control is reset focus when moving the mouse via script. However, you cannot replace focus with hover via script, so the only option is to write your own interface elements based on Node2D and sprites or TextureRect + Labels.

UPD: I finally decided to create a separate project to try to solve everything using only standard elements and it's just awful. Global script:
```gdscript
extends Node

var sb_hover: StyleBoxFlat = preload("res://custom_control/button_hover.stylebox")
var sb_hover_pressed: StyleBoxFlat = preload("res://custom_control/button_hover_pressed.stylebox")
var sbe: StyleBoxEmpty = preload("res://custom_control/def_empty.stylebox")

func find_by_class(node: Node, _class_name: String, result : Array) -> void:
	if node.is_class(_class_name):
		result.push_back(node)
	for c in node.get_children():
		find_by_class(c, _class_name, result)

func _replace_focus_with_hover() -> void:
	var focused = get_viewport().gui_get_focus_owner()
	if get_viewport().gui_get_hovered_control() != null:
		get_viewport().gui_get_hovered_control().grab_focus()
	if focused is Button and focused.focus_entered:
		focused.add_theme_stylebox_override("pressed", sbe)
		focused.add_theme_stylebox_override("hover_pressed", sbe)
		if focused.is_pressed():
			focused.add_theme_stylebox_override("focus", sb_hover_pressed)
		else:
			focused.add_theme_stylebox_override("focus", sb_hover)
	var tmp_arr: Array
	find_by_class($"..", "Button", tmp_arr)
	for n in tmp_arr:
		if n != get_viewport().gui_get_focus_owner():
			n.add_theme_stylebox_override("pressed", load("res://custom_control/button_pressed.stylebox"))

func _process(delta: float) -> void:
	_replace_focus_with_hover()
```
